  1	// Global variables for storing movie and rating data
  2	let movies = [];
  3	let ratings = [];
  4	
  5	// Collaborative filtering structures (populated by buildRatingMatrix)
  6	let numUsers = 0;          // highest user id found in u.data
  7	let numMovies = 0;         // number of parsed movies
  8	let ratingMatrix = null;   // (numUsers + 1) x (numMovies + 1); 0 = "not rated"
  9	let ratingsByUser = [];    // sparse rows: [{ itemId, rating }]
 10	let ratingsByMovie = [];   // sparse columns: [{ userId, rating }]
 11	let movieById = new Map();
 12	
 13	// Genre names as defined in the u.item file
 14	const genreNames = [
 15	    "Action", "Adventure", "Animation", "Children's", "Comedy",
 16	    "Crime", "Documentary", "Drama", "Fantasy", "Film-Noir",
 17	    "Horror", "Musical", "Mystery", "Romance", "Sci-Fi",
 18	    "Thriller", "War", "Western"
 19	];
 20	
 21	// Primary function to load data from files
 22	async function loadData() {
 23	    try {
 24	        movies = [];
 25	        ratings = [];
 26	
 27	        // Load and parse movie data
 28	        const moviesResponse = await fetch('u.item');
 29	        if (!moviesResponse.ok) {
 30	            throw new Error(`Failed to load movie data: ${moviesResponse.status}`);
 31	        }
 32	        // MovieLens u.item is Latin-1, not UTF-8.
 33	        const moviesText = new TextDecoder('iso-8859-1').decode(await moviesResponse.arrayBuffer());
 34	        parseItemData(moviesText);
 35	
 36	        // Load and parse rating data
 37	        const ratingsResponse = await fetch('u.data');
 38	        if (!ratingsResponse.ok) {
 39	            throw new Error(`Failed to load rating data: ${ratingsResponse.status}`);
 40	        }
 41	        const ratingsText = await ratingsResponse.text();
 42	        parseRatingData(ratingsText);
 43	
 44	        // Derive matrix dimensions, then build the rating matrix
 45	        numUsers = ratings.reduce((max, r) => Math.max(max, r.userId), 0);
 46	        numMovies = movies.length;
 47	        buildRatingMatrix();
 48	    } catch (error) {
 49	        console.error('Error loading data:', error);
 50	        const errorTarget = document.getElementById('user-based-result');
 51	        if (errorTarget) {
 52	            errorTarget.innerHTML = `<p class="error">Error: ${error.message}. Please make sure u.item and u.data are in the correct location.</p>`;
 53	        }
 54	        const itemErrorTarget = document.getElementById('item-based-result');
 55	        if (itemErrorTarget) {
 56	            itemErrorTarget.innerHTML = '<p class="error">Movie data could not be loaded.</p>';
 57	        }
 58	        throw error; // Re-throw so script.js can handle the error
 59	    }
 60	}
 61	
 62	// Parse movie data from u.item format
 63	function parseItemData(text) {
 64	    const lines = text.split('\n');
 65	
 66	    for (const line of lines) {
 67	        if (line.trim() === '') continue;
 68	
 69	        const fields = line.split('|');
 70	        if (fields.length < 5) continue; // Skip invalid lines
 71	
 72	        const id = parseInt(fields[0]);
 73	        const title = fields[1];
 74	
 75	        // Extract genres (last 19 fields)
 76	        const genreValues = fields.slice(5, 24).map(value => parseInt(value));
 77	        const genres = genreNames.filter((_, index) => genreValues[index] === 1);
 78	
 79	        movies.push({ id, title, genres });
 80	    }
 81	}
 82	
 83	// Parse rating data from u.data format
 84	function parseRatingData(text) {
 85	    const lines = text.split('\n');
 86	
 87	    for (const line of lines) {
 88	        if (line.trim() === '') continue;
 89	
 90	        const fields = line.split('\t');
 91	        if (fields.length < 4) continue; // Skip invalid lines
 92	
 93	        const userId = parseInt(fields[0]);
 94	        const itemId = parseInt(fields[1]);
 95	        const rating = parseFloat(fields[2]);
 96	        const timestamp = parseInt(fields[3]);
 97	
 98	        ratings.push({ userId, itemId, rating, timestamp });
 99	    }
100	}
101	
102	// ---------------------------------------------------------------------------
103	// Build the user-item rating matrix.
104	//
105	// Shape: (numUsers + 1) x (numMovies + 1), indexed by raw id, so that
106	//   ratingMatrix[userId][movieId] === rating
107	// and a missing entry is 0. MovieLens ratings are 1-5, so 0 is unambiguous.
108	//
109	// Store the result in the global variable `ratingMatrix`.
110	// ---------------------------------------------------------------------------
111	function buildRatingMatrix() {
112	    ratingMatrix = Array.from(
113	        { length: numUsers + 1 },
114	        () => new Uint8Array(numMovies + 1)
115	    );
116	    ratingsByUser = Array.from({ length: numUsers + 1 }, () => []);
117	    ratingsByMovie = Array.from({ length: numMovies + 1 }, () => []);
118	    movieById = new Map(movies.map(movie => [movie.id, movie]));
119	
120	    for (const { userId, itemId, rating } of ratings) {
121	        if (!ratingMatrix[userId] || !movieById.has(itemId)) continue;
122	        ratingMatrix[userId][itemId] = rating;
123	        ratingsByUser[userId].push({ itemId, rating });
124	        ratingsByMovie[itemId].push({ userId, rating });
125	    }
126	
127	    // Sorted sparse columns let item similarity visit only users who rated
128	    // either film, rather than scanning every entry of the dense matrix.
129	    for (const column of ratingsByMovie) {
130	        column.sort((a, b) => a.userId - b.userId);
131	    }
132	}

