  1	// ---------------------------------------------------------------------------
  2	// HW3 — Collaborative Filtering core
  3	//
  4	// Missing-value strategy: compare only co-rated entries. A zero in the matrix
  5	// means "not rated" and never contributes to a dot product or a norm.
  6	// ---------------------------------------------------------------------------
  7	
  8	// Initialize the application when the window loads
  9	window.onload = async function() {
 10	    const userBased = document.getElementById('user-based-result');
 11	    const itemBased = document.getElementById('item-based-result');
 12	
 13	    try {
 14	        userBased.innerHTML = '<p>Loading movie data...</p>';
 15	        itemBased.innerHTML = '<p>Loading movie data...</p>';
 16	
 17	        await loadData();
 18	
 19	        populateUserDropdown();
 20	
 21	        userBased.innerHTML = '<p>Data loaded. Select a user.</p>';
 22	        itemBased.innerHTML = '<p>Data loaded. Select a user.</p>';
 23	    } catch (error) {
 24	        console.error('Initialization error:', error);
 25	        // The error message is already shown by data.js
 26	    }
 27	};
 28	
 29	// Populate the user dropdown with one option per user id found in u.data
 30	function populateUserDropdown() {
 31	    const selectElement = document.getElementById('user-select');
 32	
 33	    // Clear existing options except the first placeholder
 34	    while (selectElement.options.length > 1) {
 35	        selectElement.remove(1);
 36	    }
 37	
 38	    for (let userId = 1; userId <= numUsers; userId++) {
 39	        const option = document.createElement('option');
 40	        option.value = userId;
 41	        option.textContent = `User ${userId}`;
 42	        selectElement.appendChild(option);
 43	    }
 44	}
 45	
 46	// ---------------------------------------------------------------------------
 47	// Cosine similarity between two rating vectors.
 48	//
 49	// Compare only co-rated (non-zero) entries, per the missing-value strategy
 50	// you chose above. Return 0 when the denominator is 0 (that is, when the two
 51	// vectors share no rated items). See week3/readme.md section 5.3.
 52	//
 53	// Inputs: two arrays of equal length (slice the rating matrix column or row).
 54	// Output: a number in [0, 1].
 55	// ---------------------------------------------------------------------------
 56	function cosineSimilarity(a, b) {
 57	    let dot = 0;
 58	    let normA = 0;
 59	    let normB = 0;
 60	
 61	    for (let index = 1; index < a.length; index++) {
 62	        if (a[index] === 0 || b[index] === 0) continue;
 63	        dot += a[index] * b[index];
 64	        normA += a[index] * a[index];
 65	        normB += b[index] * b[index];
 66	    }
 67	
 68	    return normA && normB ? dot / Math.sqrt(normA * normB) : 0;
 69	}
 70	
 71	function getNearestUsers(activeUserId, limit = 20) {
 72	    const activeRatings = ratingMatrix[activeUserId];
 73	    if (!activeRatings) return [];
 74	
 75	    const neighbors = [];
 76	    for (let userId = 1; userId <= numUsers; userId++) {
 77	        if (userId === activeUserId) continue;
 78	        const similarity = cosineSimilarity(activeRatings, ratingMatrix[userId]);
 79	        if (similarity > 0) neighbors.push({ userId, similarity });
 80	    }
 81	
 82	    return neighbors
 83	        .sort((a, b) => b.similarity - a.similarity || a.userId - b.userId)
 84	        .slice(0, limit);
 85	}
 86	
 87	// ---------------------------------------------------------------------------
 88	// User-Based CF.
 89	//
 90	// Return the top-K recommendations for the active user as an array of
 91	// { title, score }, sorted by score descending.
 92	//
 93	// Suggested steps (week3/readme.md section 5.4):
 94	//   1. compare the active user's rating vector against every other user
 95	//   2. take the N most similar users with positive similarity (e.g. N = 20)
 96	//   3. for each movie the active user has NOT rated, predict a score as the
 97	//      similarity-weighted average of those users' ratings
 98	//   4. sort and take the top K
 99	// ---------------------------------------------------------------------------
