130	function itemSimilarity(firstItemId, secondItemId) {
131	    const first = ratingsByMovie[firstItemId];
132	    const second = ratingsByMovie[secondItemId];
133	    let firstIndex = 0;
134	    let secondIndex = 0;
135	    let dot = 0;
