137	    let normSecond = 0;
138	
139	    while (firstIndex < first.length && secondIndex < second.length) {
140	        const firstRating = first[firstIndex];
141	        const secondRating = second[secondIndex];
142	        if (firstRating.userId < secondRating.userId) {
143	            firstIndex++;
144	        } else if (firstRating.userId > secondRating.userId) {
145	            secondIndex++;
