179	
180	        let weightedSum = 0;
181	        let weightSum = 0;
182	        const contributors = [];
183	        for (const { itemId: ratedItemId, rating } of ratedMovies) {
184	            const similarity = itemSimilarity(itemId, ratedItemId);
