* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Helvetica', 'Arial', sans-serif;
    background-color: #f4f7f6;
    color: #333;
    line-height: 1.6;
    padding: 20px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    min-height: 100vh;
}

.container {
    background-color: white;
    border-radius: 10px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    padding: 30px;
    width: 90%;
    max-width: 1200px;
}

h1 {
    text-align: center;
    margin-bottom: 15px;
    color: #2c3e50;
}

p {
    text-align: center;
    margin-bottom: 20px;
    color: #7f8c8d;
}

.controls {
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 25px;
}

#user-select {
    padding: 12px;
    border: 1px solid #ddd;
    border-radius: 5px;
    font-size: 16px;
    background-color: #f9f9f9;
    transition: border-color 0.3s;
}

#user-select:focus {
    border-color: #3498db;
    outline: none;
}

#recommend-btn {
    padding: 12px 20px;
    background-color: #3498db;
    color: white;
    border: none;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    transition: background-color 0.3s;
}

#recommend-btn:hover {
    background-color: #2980b9;
}

#result-box {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 15px;
}

.result-column {
    background-color: #f8f9fa;
    padding: 20px;
    border-radius: 5px;
    border-left: 4px solid #3498db;
    min-width: 0;
    overflow-wrap: anywhere;
}

.result-column h2 {
    font-size: 1.05rem;
    color: #2c3e50;
    margin-bottom: 10px;
    text-align: left;
}

.result-column p,
.result-column ul {
    text-align: left;
    color: #2c3e50;
    margin: 0;
}

.result-column ul {
    padding-left: 20px;
}

.recommendation-list,
.evidence-list {
    padding-left: 24px;
}

.recommendation-list > li + li,
.evidence-list > li + li {
    margin-top: 12px;
}

.score {
    display: block;
    color: #526579;
    font-size: 0.9rem;
}

.explanation {
    margin-top: 22px;
    padding-top: 14px;
    border-top: 1px solid #d8e1e7;
}

.explanation summary {
    cursor: pointer;
    color: #175d8f;
    font-weight: 600;
}

.explanation-content {
    margin-top: 12px;
    font-size: 0.9rem;
}

.method-list {
    margin-bottom: 12px !important;
}

.explanation-content li {
    margin-bottom: 5px;
}

@media (max-width: 640px) {
    #result-box {
        grid-template-columns: 1fr;
    }
}

.error {
    color: #e74c3c;
}
