                    <summary>How were these recommendations made?</summary>
                    <div class="explanation-content"></div>
                </details>
            </div>
            <div class="result-column">
                <h2>Item-Based CF</h2>
                <div id="item-based-result"><p>Please wait, loading data...</p></div>
                <details id="item-based-explanation" class="explanation" hidden>
                    <summary>How were these recommendations made?</summary>
                    <div class="explanation-content"></div>
                </details>
            </div>
        </div>
    </div>

    <script src="data.js"></script>
    <script src="script.js"></script>
</body>
