            if (observed !== 0) {
                matrix[userId][itemId] = observed;
                continue;
            }
            let estimate = globalMean + userBias[userId] + itemBias[itemId];
            for (let factor = 0; factor < factors; factor++) {
                estimate += userFactors[userId][factor] * itemFactors[itemId][factor];
            }
