const fs = require('fs');
const vm = require('vm');
const assert = require('assert');
const path = '/Users/raimova-al/Documents/study/master/res_sys/llm-4-res-sys/week3/';
const elements = new Map();
for (const id of ['user-select', 'user-based-result', 'item-based-result', 'user-based-explanation', 'item-based-explanation']) {
    elements.set(id, { value: '', innerHTML: '', hidden: true, open: false,
        querySelector: () => ({ set innerHTML(value) { elements.get(id).report = value; } }) });
}
const context = vm.createContext({ console, window: {}, document: { getElementById: id => elements.get(id) }, TextDecoder });
vm.runInContext(fs.readFileSync(path + 'data.js', 'utf8'), context);
vm.runInContext(fs.readFileSync(path + 'script.js', 'utf8'), context);
vm.runInContext(`parseItemData(${JSON.stringify(fs.readFileSync(path + 'u.item', 'latin1'))});`, context);
vm.runInContext(`parseRatingData(${JSON.stringify(fs.readFileSync(path + 'u.data', 'utf8'))});`, context);
vm.runInContext('numUsers = ratings.reduce((max, r) => Math.max(max, r.userId), 0); numMovies = movies.length; buildRatingMatrix();', context);
assert.strictEqual(vm.runInContext('ratingMatrix.length', context), 944);
assert.strictEqual(vm.runInContext('ratingMatrix[196][242]', context), 3);
assert.strictEqual(vm.runInContext('cosineSimilarity([0, 5, 0], [0, 4, 3])', context), 1);
assert.strictEqual(vm.runInContext('cosineSimilarity([0, 5, 0], [0, 0, 3])', context), 0);
for (const userId of [1, 196, 943]) {
    console.time('recommend user ' + userId);
    const neighbors = vm.runInContext(`getNearestUsers(${userId})`, context);
    const users = vm.runInContext(`getUserBasedRecommendations(${userId})`, context);
    const items = vm.runInContext(`getItemBasedRecommendations(${userId})`, context);
    console.timeEnd('recommend user ' + userId);
    assert.strictEqual(neighbors.length, 20);
    assert.strictEqual(users.length, 5);
    assert.strictEqual(items.length, 5);
    for (const list of [users, items]) {
        for (let i = 0; i < list.length; i++) {
            const movie = list[i];
            assert(vm.runInContext(`ratingMatrix[${userId}][${movie.itemId}]`, context) === 0);
            assert(movie.score >= 1 && movie.score <= 5);
            assert(movie.contributors.length > 0);
            const weightedMean = movie.contributors.reduce((sum, source) => sum + source.similarity * source.rating, 0) /
                movie.contributors.reduce((sum, source) => sum + source.similarity, 0);
            assert(Math.abs(movie.score - weightedMean) < 1e-10);
            if (i) assert(list[i - 1].score >= movie.score);
        }
    }
    elements.get('user-select').value = String(userId);
    vm.runInContext('getRecommendations()', context);
    assert(!elements.get('user-based-explanation').hidden);
    assert(!elements.get('item-based-explanation').hidden);
    assert((elements.get('user-based-explanation').report.match(/<strong>User /g) || []).length === 3);
    const sourceFilmsShown = (elements.get('item-based-explanation').report.match(/ — your rating /g) || []).length;
    assert(sourceFilmsShown >= 5 && sourceFilmsShown <= 15);
    console.log('item source films shown:', sourceFilmsShown);
    console.log(userId, 'user top:', users.map(x => `${x.title} (${x.score.toFixed(2)})`).join('; '));
    console.log(userId, 'item top:', items.map(x => `${x.title} (${x.score.toFixed(2)})`).join('; '));
}
assert.strictEqual(vm.runInContext(`escapeHtml('<script>"&')`, context), '&lt;script&gt;&quot;&amp;');
console.log('All checks passed');

