.prediction-result[hidden] {
    display: none;
}

.prediction-result h3 {
    color: #2c3e50;
    font-size: 1.05rem;
    margin-bottom: 12px;
}

.prediction-scores {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.prediction-score {
    background: white;
    border-left: 4px solid #247f75;
    border-radius: 5px;
    padding: 16px;
}

